const host=window.parent;
const doc=host.document;
if(!doc.getElementById('mnemosyne-resume-box')) {
  const box=doc.createElement('div');box.id='mnemosyne-resume-box';
  box.style.cssText='position:fixed;bottom:12px;right:12px;z-index:10000;background:#20242d;color:#eee;padding:12px;max-width:480px;max-height:70vh;overflow:auto';
  const button=doc.createElement('button');button.textContent='补完2份摘要并核验';
  const status=doc.createElement('pre');status.id='mnemosyne-resume-status';status.style.whiteSpace='pre-wrap';
  status.textContent='入口已就绪。请先回复Codex，等收集器启动后再点击。';
  box.append(button,status);doc.body.append(box);
  button.onclick=()=>{
    button.disabled=true;status.textContent='正在核对原会话并补完摘要；请勿刷新、生成或重复点击。';
    const script=doc.createElement('script');script.type='module';
    script.src='http://127.0.0.1:19375/packages/bridge/native-resume-launch.mjs';
    script.onerror=()=>{status.textContent='检查入口未加载，请返回Codex；不要重复点击。';};
    doc.body.append(script);
  };
  window.addEventListener('pagehide',()=>box.remove(),{once:true});
}
